#pragma once#include "ISharedWrapper.h"template<typename T>struct SSharedWrapper : ISharedWrapper{  T *pField;  operator T*()  {    return pField;  }  virtual CBase* GetBase()  {    return pField;  }  virtual BYTE* GetField( eHcdVType *pType = NULL, tHcdVarSizeType_ *pVarSize = NULL )  {    if( pType )      *pType = (eHcdVType)T::PVtype;    if( pVarSize )      *pVarSize = sizeof(pField->PV);    return (BYTE*)&pField->PV;  }  operator tAnalog32&()  {    return pField->PV;  }  void operator = ( tAnalog32 thr )  {    pField->PV = thr;  }  void operator = ( tDigital32 thr )  {    pField->PV = thr;  }  void operator = ( SSharedWrapper<T> &thr )  {    pField->PV = thr.pField->PV;  }};class KShareContainer{  struct Srecord  {    SParamInfo varInfo;    Srecord *pNext;    ISharedWrapper *pShara;    NEWHCD  };  Srecord *pFirst, *pLast;  DWORD added;public:  KShareContainer() : pFirst( NULL ), pLast( NULL ), added( 0 )  {}  void operator << ( ISharedWrapper *pN )  {    if( !pFirst )      pLast = pFirst = new Srecord;    else    {      pLast->pNext = new Srecord;      pLast = pLast->pNext;    }    ++added;    pLast->pShara = pN;    pLast->varInfo.Addr = pLast->pShara->GetField( &pLast->varInfo.evtType, &pLast->varInfo.size );    pLast->varInfo.pszName = pLast->pShara->pszName;    pLast->varInfo.pszLgxParamName = pLast->pShara->pszOtherName;    pLast->varInfo.flags |= SVarInfo::efSaveInState;  }  ISharedWrapper* GetShare( LPCSTR pszName )  {    for( Srecord *p = pFirst; p; p = p->pNext )    {      if( strcmp(p->pShara->pszName, pszName) )      {        if( !p->pShara->pszOtherName )          continue;        if( strcmp(p->pShara->pszOtherName, pszName) )          continue;      }      return p->pShara;    }    return NULL;  }  void EnumFields( size_t &s, SParamInfo *pVars, size_t nCount )  {    if( !nCount )    {      s += added;      return;    }    for( Srecord *p = pFirst; p && s<nCount; p = p->pNext, ++s )    {      pVars[s] = p->varInfo;    }  }};template<typename T>static SSharedWrapper<T>* CreateField( SSharedWrapper<T> &pnt, LPCSTR pszHmiTagName, LPCSTR pszRealField, LPCSTR pszOtherName, int domain ){  char szBigName[48];  sprintf_s( szBigName, "%s.%s", pszHmiTagName, pszRealField);  pnt.pField = (T*)KMemoryServiceHCD::Instance().CreateSharedObj( szBigName, T::TypeID, domain );  pnt.pszName = pszRealField;  pnt.pszOtherName = pszOtherName;  return &pnt;}